/// <summary>
/// PricingAttribute of table <c>CustTable</c> field CustGroup.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Customer, UPSPricingAttributeSourceLevel::Header)]
internal class UPSPricingAttributeCustTableCustGroup extends UPSPricingAttributeCustTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(CustTable, CustGroup);
}

public Set getAllowedValues()
{
    var         ret = new Set(Types::String);
    CustTable   custTable;

    while select CustGroup from custTable
        group by CustGroup
    {
        ret.add(custTable.CustGroup);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(CustTable, CustGroup));
    qbr.value(queryValue(_value));
}
